/**
 * Dynamic variables (`{{$guid}}`, `{{$randomFirstName}}`, …) — the ONE table
 * and the ONE `{{…}}` substitution loop for every surface: Send (renderer
 * `variable-resolver.ts`), Run and Mock (main `lib/variable-resolver.ts`,
 * `mock/template.ts`), script `replaceIn`, and the editor autocomplete lists.
 *
 * There used to be three hand-kept copies of the generators (renderer, main,
 * mock) and two autocomplete lists; a generator added to one copy was a
 * Send-works / Run-breaks bug waiting to happen (the issue #4 class).
 *
 * The Postman names (all 118) are generated by Postman's OWN table —
 * postman-collection `lib/superstring/dynamic-variables.js`, the code
 * Postman / Newman run — so output shapes match Postman exactly (issue #281).
 * postman-collection is already a dependency (the script sandbox's
 * `require('postman-collection')`), and the faker 5.5.3 it uses is CommonJS,
 * so this adds no package and no ESM-only module to the main bundle.
 *
 * An unknown `{{$name}}` is left exactly as written, as Postman does (it used
 * to lose its braces here and ship as the bare text `$name`).
 *
 * Testnizer extensions Postman does not have: `$randomInt(min,max)`,
 * `$randomString` / `$randomString(n)`, `$randomName`, `$datetime(format)`.
 * Mock presets use them; keep them.
 */
import postmanDynamicGenerators from 'postman-collection/lib/superstring/dynamic-variables'

export interface DynamicVariable {
  /** Name including the `$`, e.g. `$guid`. Function forms show their args. */
  name: string
  description: string
  /** Postman ships this name (false = Testnizer extension). */
  postman: boolean
}

// ─── Testnizer extensions ────────────────────────────────────────

function randomInt(min: number, max: number): number {
  return Math.floor(Math.random() * (max - min + 1)) + min
}

const ALNUM_MIXED = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'

function randomChars(len: number): string {
  let out = ''
  for (let i = 0; i < len; i++) out += ALNUM_MIXED.charAt(randomInt(0, ALNUM_MIXED.length - 1))
  return out
}

// Testnizer's own wordlists for $randomName (kept from before).
const FIRST_NAMES = [
  'Alice', 'Bob', 'Carol', 'David', 'Eve', 'Frank', 'Grace', 'Henry', 'Ivy', 'Jack', 'Kate',
  'Leo', 'Maya', 'Noah', 'Olivia', 'Paul', 'Quinn', 'Rose', 'Sam', 'Tara', 'Uma', 'Victor',
  'Wendy', 'Xander',
] // prettier-ignore
const LAST_NAMES = [
  'Johnson', 'Smith', 'Williams', 'Brown', 'Jones', 'Davis', 'Miller', 'Wilson', 'Moore',
  'Taylor', 'Anderson', 'Thomas', 'Jackson', 'White', 'Harris', 'Martin', 'Thompson', 'Garcia',
] // prettier-ignore

function pick(list: readonly string[]): string {
  return list[randomInt(0, list.length - 1)]
}

function formatDatetime(format: string): string {
  const now = new Date()
  return format
    .replace('YYYY', String(now.getFullYear()))
    .replace('MM', String(now.getMonth() + 1).padStart(2, '0'))
    .replace('DD', String(now.getDate()).padStart(2, '0'))
    .replace('HH', String(now.getHours()).padStart(2, '0'))
    .replace('mm', String(now.getMinutes()).padStart(2, '0'))
    .replace('ss', String(now.getSeconds()).padStart(2, '0'))
}

interface Generator extends DynamicVariable {
  generate(): string
}

const EXTENSIONS: Generator[] = [
  {
    name: '$randomName',
    postman: false,
    description: 'Random full name',
    generate: () => `${pick(FIRST_NAMES)} ${pick(LAST_NAMES)}`,
  },
  {
    name: '$randomString',
    postman: false,
    description: 'Random 8-character alphanumeric string',
    generate: () => randomChars(8),
  },
]

/** Function forms (Testnizer extensions): `$randomInt(min,max)` & co. */
const FUNCTION_FORMS: DynamicVariable[] = [
  { name: '$randomInt(min,max)', postman: false, description: 'Random integer in range' },
  {
    name: '$randomString(n)',
    postman: false,
    description: 'Random alphanumeric string of length n',
  },
  {
    name: '$datetime(format)',
    postman: false,
    description: 'Current date/time (YYYY MM DD HH mm ss)',
  },
]

// ─── the table ───────────────────────────────────────────────────

/** Postman's generators: name → value as Postman prints it. */
const POSTMAN: Generator[] = Object.entries(postmanDynamicGenerators).map(([name, def]) => ({
  name,
  postman: true,
  description: def.description,
  // Called on the descriptor, exactly as postman-collection's Substitutor does.
  generate: () => String(def.generator()),
}))

const BY_NAME = new Map<string, Generator>(
  [...POSTMAN, ...EXTENSIONS].map((g) => [g.name, g] as const),
)

/** Every dynamic variable, in autocomplete order (no generator functions). */
export const DYNAMIC_VARIABLES: readonly DynamicVariable[] = [
  ...POSTMAN,
  ...EXTENSIONS,
  ...FUNCTION_FORMS,
].map(({ name, description, postman }) => ({ name, description, postman }))

const FUNCTION_NAMES = ['randomInt', 'randomString', 'datetime']

function resolveFunctionForm(name: string, args: string): string | undefined {
  switch (name) {
    case 'randomInt': {
      const parts = args.split(',').map((s) => parseInt(s.trim(), 10))
      if (parts.length === 2 && !isNaN(parts[0]) && !isNaN(parts[1])) {
        return String(randomInt(parts[0], parts[1]))
      }
      return String(randomInt(0, 1000))
    }
    case 'randomString': {
      const len = parseInt(args.trim(), 10)
      return randomChars(isNaN(len) ? 8 : len)
    }
    case 'datetime':
      return formatDatetime(args.replace(/['"]/g, '').trim())
    default:
      return undefined
  }
}

/**
 * Value of one dynamic expression (`$guid`, `$randomInt(1,5)`), or `undefined`
 * when the name is unknown — the caller then leaves the placeholder as written.
 */
export function resolveDynamicVariable(expr: string): string | undefined {
  const fn = expr.match(/^\$(\w+)\((.+)\)$/)
  if (fn) return resolveFunctionForm(fn[1], fn[2])
  return BY_NAME.get(expr)?.generate()
}

/** Is `expr` a dynamic variable this build can produce? */
export function isKnownDynamicVariable(expr: string): boolean {
  const fn = expr.match(/^\$(\w+)\((.+)\)$/)
  if (fn) return FUNCTION_NAMES.includes(fn[1])
  return BY_NAME.has(expr)
}

/** Bound on chained `{{a}} → {{b}} → …` resolution; circular refs hit the cap. */
export const MAX_RESOLVE_DEPTH = 10

const PLACEHOLDER = /\{\{([^}]+)\}\}/g

/**
 * Resolve `{{var}}` and `{{$dynamic}}` placeholders. `lookup` answers a plain
 * variable name (undefined = unknown). Unknown variables stay `{{name}}`;
 * unknown dynamic variables stay EXACTLY as written. Repeats up to
 * MAX_RESOLVE_DEPTH passes so a value may reference another variable.
 */
export function resolveTemplate(
  template: string,
  lookup: (name: string) => string | undefined,
): string {
  if (!template) return template
  const substitute = (input: string): string =>
    input.replace(PLACEHOLDER, (match, expression: string) => {
      const trimmed = expression.trim()
      if (trimmed.startsWith('$')) return resolveDynamicVariable(trimmed) ?? match
      const value = lookup(trimmed)
      return value === undefined ? `{{${trimmed}}}` : value
    })
  let current = template
  for (let i = 0; i < MAX_RESOLVE_DEPTH; i++) {
    const next = substitute(current)
    if (next === current) return next
    current = next
  }
  return current
}

/** Replace ONLY known `{{$dynamic}}` placeholders; every other `{{…}}` is untouched. */
export function resolveDynamicPlaceholders(template: string): string {
  if (!template) return template
  return template.replace(PLACEHOLDER, (match, expression: string) => {
    const trimmed = expression.trim()
    if (!trimmed.startsWith('$')) return match
    return resolveDynamicVariable(trimmed) ?? match
  })
}
